        ((SELECT COALESCE(MAX(id),0)+8 FROM public.tcg_type_master), 'pokemon', 'ポケモンカードゲーム', 'Pokemon Trading Card Game', 280)
    ON CONFLICT (code) DO NOTHING;
END $$;

